SELECT ?name ?ts WHERE {
  ?p a brick:Power .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  ?p rdfs:label ?name .
  FILTER (?name IN ("AHU02","SupplyFan_AHU02","SupplyFan_AHU03"))
}

SELECT ?name ?uri WHERE {
  ?p rdfs:label ?name .
  FILTER (LCASE(?name) LIKE "%ahu02%" || LCASE(?name) LIKE "%ahu03%")
}

SELECT ?s ?o WHERE {
  ?s a brick:AirHandlingUnit OR ?s a brick:Fan .
  ?s rdfs:label ?o .
}

